-- =============================================================================
-- Armana — Migration 0039 : ouverture à toute la France (métropole et Corse)
-- =============================================================================
-- ⚠ À APPLIQUER APRÈS LA 0038. En UNE fois dans le SQL Editor : une erreur
-- annule tout en silence, la vérification finale dit si tout est passé.
--
-- Armana couvrait PACA et la Drôme (7 départements). Elle couvre désormais les
-- 96 départements de métropole et de Corse, rangés en 13 régions.
--
-- CE QUI CHANGE
--   A. table `departements` : les 96 codes, leur nom et leur RÉGION. Elle
--      remplace les listes de codes écrites en dur dans cinq fonctions et
--      dans une contrainte — ajouter un département n'exigera plus de les
--      réécrire toutes ;
--   B. `dept_contours` : les 89 contours manquants (allégés ~0,8 km, même jeu
--      Etalab). Les 7 déjà en place ne bougent pas ;
--   C. la contrainte `events_dept_valide` lit la table ;
--   D. rattrapage des événements sans département ;
--   E. les cinq fonctions qui filtraient sur la liste, réémises à l'identique
--      de leur dernière version (0026) — seule la liste change ;
--   F. `moderateurs_par_region()` : combien de modérateurs par région, pour
--      l'invitation proposée après l'inscription (seuil : 5).
-- =============================================================================

-- -----------------------------------------------------------------------------
-- A. Les départements et leur région
-- -----------------------------------------------------------------------------
create table if not exists public.departements (
  code        text primary key,
  nom         text not null,
  region_code text not null,
  region_nom  text not null
);

alter table public.departements enable row level security;
-- Information publique (noms officiels) : lecture pour tous, écriture pour
-- personne côté API.
drop policy if exists departements_lecture on public.departements;
create policy departements_lecture on public.departements for select using (true);
grant select on public.departements to anon, authenticated;

